int ipp_table_count(void) { return (int)(sizeof T / sizeof *T); }
const char *ipp_table_name(int i) { return T[i].name; }
void *ipp_table_fn(int i) { return T[i].fn; }
int ipp_table_impl(int i) { return T[i].impl; }
#include <string.h>
void *ipp_lookup(const char *name) { int lo = 0, hi = (int)(sizeof T / sizeof *T) - 1;
  while (lo <= hi) { int m = (lo + hi) / 2, c = strcmp(name, T[m].name); if (!c) return T[m].fn; if (c < 0) hi = m - 1; else lo = m + 1; }
  return 0; }
/* fail-fast 検証用: 名前で引いた関数を引数なしで呼ぶ (stub なら trap し ipp_unimpl_name() に名前が残る) */
int ipp_call0(const char *name) { void *f = ipp_lookup(name); return f ? ((int (*)(void))f)() : -1; }
